'use strict';
const state = {drafts:{}, checks:{}, quiz:{}};
let dirty=false, toastTimer;
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function route(){const parts=location.hash.slice(1).split('/');if(parts[0]==='aula'){const lesson=lessons.find(l=>l.id===Number(parts[1]));if(lesson)return {page:'aula',lesson,tab:['conteudo','pratica','materiais'].includes(parts[2])?parts[2]:'conteudo'};return{page:'404'}}return{page:['inicio','caso','guia'].includes(parts[0])?parts[0]:(parts[0]?'404':'inicio')}}
function nav(r){$('#nav').innerHTML=`<a class="nav-link ${r.page==='inicio'?'active':''}" href="#inicio" ${r.page==='inicio'?'aria-current="page"':''}><span class="nav-num">⌂</span><span class="nav-text">Visão geral</span></a>`+lessons.map(l=>`<a class="nav-link ${r.lesson?.id===l.id?'active':''}" href="#aula/${l.id}/conteudo" ${r.lesson?.id===l.id?'aria-current="page"':''}><span class="nav-num">0${l.id}</span><span class="nav-text">${l.short}<small>Encontro ${l.id} · 3 horas</small></span></a>`).join('')+`<div class="divider"></div><a class="nav-link ${r.page==='caso'?'active':''}" href="#caso" ${r.page==='caso'?'aria-current="page"':''}><span class="nav-num">↗</span><span class="nav-text">Caso integrador</span></a><a class="nav-link ${r.page==='guia'?'active':''}" href="#guia" ${r.page==='guia'?'aria-current="page"':''}><span class="nav-num">?</span><span class="nav-text">Guia da disciplina</span></a>`}
function home(){return `<section class="hero"><div><span class="pill">PÓS-GRADUAÇÃO · TRILHA APLICADA</span><h1>Gestão de Projetos<br>com IA</h1><p class="lead">Do primeiro briefing à defesa executiva. Aprenda, pratique e desenvolva um projeto com apoio de ChatGPT e Claude.</p><div class="actions"><a class="btn" href="#aula/1/conteudo">Começar pelo encontro 1 <span aria-hidden="true">→</span></a><a class="btn secondary" href="#guia">Como funciona</a></div></div><div class="hero-card"><span class="eyebrow">APRENDER FAZENDO</span><span class="big">04</span><h3>Encontros que<br>se conectam.</h3><p>Um caso, novas evidências e decisões cada vez mais fundamentadas.</p><a href="#caso">Conheça seu projeto <span aria-hidden="true">↗</span></a></div></section><div class="section-title"><h2>Sua trilha de aprendizagem</h2><span>4 encontros · 12 horas</span></div><section class="grid" aria-label="Encontros">${lessons.map(l=>`<a class="card" href="#aula/${l.id}/conteudo"><div class="card-top"><span class="number">0${l.id}</span><span class="time">3 horas · Online</span></div><h3>${l.title}</h3><p>${l.description}</p><div class="card-bottom"><span>${l.outcome}</span><span class="arrow" aria-hidden="true">↗</span></div></a>`).join('')}</section><div class="bottom-grid"><section class="case-banner"><span class="eyebrow">CASO INTEGRADOR / FLUXO CLARO</span><h3>Um novo fluxo de demandas.<br>Decisões reais em um caso fictício.</h3><p>Planeje a implantação, responda a uma mudança e avalie o benefício. Todos os dados necessários estão no caso.</p><a href="#caso">Abrir briefing e dados do projeto →</a></section><section class="how"><h3>Em cada encontro</h3><div class="step"><b>1</b><span>Estude os conceitos e examine as evidências.</span></div><div class="step"><b>2</b><span>Execute a prática na IA disponível ao grupo.</span></div><div class="step"><b>3</b><span>Revise, registre sua decisão e baixe a entrega.</span></div></section></div>`}
function rail(l){return `<div class="rail"><section class="rail-card"><h3>Ao final deste encontro</h3><p>${l.outcome}</p><ul>${l.tags.map(t=>`<li>${t}</li>`).join('')}</ul></section><section class="rail-card"><h3>Roteiro · 180 minutos</h3>${l.schedule.map(s=>`<div class="time-row"><span>${s[0]}</span><span>${s[1]}</span></div>`).join('')}</section><section class="rail-card"><h3>Antes de começar</h3><p>Use o mesmo caso nos quatro encontros. Metas propostas e hipóteses devem ficar explícitas.</p><a class="source" href="#caso">Consultar o caso integrador</a></section></div>`}
function quiz(l){const chosen=state.quiz[l.id];return `<section class="quiz"><h3>Verifique seu entendimento</h3><fieldset><legend>${l.quiz.q}</legend>${l.quiz.options.map((o,i)=>`<label class="option"><input type="radio" name="quiz-${l.id}" value="${i}" ${chosen===i?'checked':''}><span>${o}</span></label>`).join('')}</fieldset><button class="btn secondary" data-action="quiz" data-id="${l.id}">Conferir resposta</button><div id="quiz-feedback" aria-live="polite"></div></section>`}
function practice(l){return `<div class="practice-intro"><span class="eyebrow">LABORATÓRIO GUIADO</span><h2>${l.outcome}</h2><p>${l.question}</p></div><h3>Passo a passo</h3><ol>${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><h3>Prompt de partida</h3><p>Leve o briefing e as fontes junto com o prompt. Execute na sua conta do ChatGPT ou Claude e revise a saída antes de registrá-la.</p><div class="prompt" id="prompt">${escapeHTML(l.prompt)}</div><div class="actions"><button class="btn secondary" data-action="copy" data-id="${l.id}">Copiar prompt</button><a class="btn secondary" href="https://chatgpt.com" target="_blank" rel="noopener noreferrer">Abrir ChatGPT ↗</a><a class="btn secondary" href="https://claude.ai" target="_blank" rel="noopener noreferrer">Abrir Claude ↗</a></div><h3>Seu caderno de prática</h3><p class="disclaimer">As respostas ficam apenas nesta aba enquanto ela estiver aberta. Baixe seu caderno antes de sair ou recarregar. Nada é enviado ao professor.</p><div class="fields">${l.fields.map((f,i)=>`<div class="field"><label for="field-${l.id}-${i}">${i+1}. ${f[0]}</label><small id="hint-${i}">${f[1]}</small><textarea id="field-${l.id}-${i}" data-field="${i}" data-lesson="${l.id}" aria-describedby="hint-${i}" placeholder="Registre a resposta revisada pelo grupo…">${escapeHTML(state.drafts[l.id]?.[i]??'')}</textarea></div>`).join('')}</div><div class="actions"><button class="btn" data-action="export" data-id="${l.id}">Baixar minhas respostas ↓</button><button class="btn secondary" data-action="template" data-id="${l.id}">Baixar modelo em branco</button></div><h3>Revisão antes da entrega</h3>${l.checks.map((c,i)=>`<label class="check"><input type="checkbox" data-check="${i}" data-lesson="${l.id}" ${state.checks[l.id]?.[i]?'checked':''}><span>${c}</span></label>`).join('')}<p class="disclaimer">Checklist de autoavaliação. A revisão e a entrega formal seguem a orientação do professor.</p>`}
function materials(l){return `<h2>Materiais do encontro</h2><p>Use estes arquivos como contexto da prática. Os modelos e o caso podem ser baixados sem acessar o Notion.</p><div class="resources"><div class="resource"><div><strong>Briefing completo · Fluxo Claro</strong><span>Dados, capacidade, ocorrência e mudança · TXT</span></div><button class="btn secondary" data-action="case">Baixar ↓</button></div><div class="resource"><div><strong>Atividades e custos estimados</strong><span>Base sintética para abrir em uma planilha · CSV</span></div><button class="btn secondary" data-action="csv">Baixar ↓</button></div><div class="resource"><div><strong>Modelo da prática ${l.id}</strong><span>${l.outcome} · Markdown</span></div><button class="btn secondary" data-action="template" data-id="${l.id}">Baixar ↓</button></div><div class="resource"><div><strong>Prompt do encontro</strong><span>Inclua as fontes do caso ao executar · TXT</span></div><button class="btn secondary" data-action="prompt-file" data-id="${l.id}">Baixar ↓</button></div></div><h3>Material de origem</h3><p>Conteúdo adaptado dos treinamentos “Claude para Gestores” e “ChatGPT Work para Gestão Ágil”, conforme a matriz integrada da disciplina.</p><p class="disclaimer">O conteúdo necessário à prática está disponível neste app.</p>`}
function lessonView(l,tab){return `<section class="lesson-head"><span class="pill">ENCONTRO 0${l.id} · 3 HORAS</span><h1>${l.title}</h1><p class="lead">${l.question}</p></section><nav class="tabs" aria-label="Seções do encontro">${[['conteudo','Conteúdo da aula'],['pratica','Prática guiada'],['materiais','Materiais']].map(([key,label])=>`<a class="tab ${key===tab?'active':''}" href="#aula/${l.id}/${key}" ${key===tab?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="reading-layout"><article class="reading">${tab==='conteudo'?l.sections.map(([title,html])=>`<h2>${title}</h2>${html}`).join('')+quiz(l)+`<div class="actions"><a class="btn" href="#aula/${l.id}/pratica">Ir para a prática →</a></div>`:tab==='pratica'?practice(l):materials(l)}</article>${rail(l)}</div><div class="pager"><a class="btn secondary" href="${l.id>1?'#aula/'+(l.id-1)+'/conteudo':'#inicio'}">← ${l.id>1?'Encontro anterior':'Visão geral'}</a><a class="btn secondary" href="${l.id<4?'#aula/'+(l.id+1)+'/conteudo':'#guia'}">${l.id<4?'Próximo encontro':'Critérios de avaliação'} →</a></div>`}
function caseView(){const blocks=caseText.split('\n\n');return `<section class="lesson-head"><span class="pill">CASO INTEGRADOR · DADOS SINTÉTICOS</span><h1>Projeto Fluxo Claro</h1><p class="lead">Implantação de um novo fluxo de entrada, priorização e acompanhamento de demandas internas.</p></section><div class="reading-layout"><article class="reading"><div class="info-grid"><div class="info"><small>Prazo desejado</small><strong>6 semanas</strong></div><div class="info"><small>Teto de custo</small><strong>R$ 18.000</strong></div></div><div class="note"><b>Simulação acadêmica</b>Todos os números, personagens e situações deste caso são fictícios. As restrições são insumos para análise, não garantia de viabilidade.</div><div class="actions"><button class="btn" data-action="case">Baixar o caso completo ↓</button><button class="btn secondary" data-action="csv">Baixar atividades · CSV</button></div>${blocks.slice(1).map(b=>{const lines=b.split('\n');return `<h2>${escapeHTML(lines[0])}</h2>${lines.slice(1).map(p=>`<p>${escapeHTML(p)}</p>`).join('')}`}).join('')}</article><div class="rail"><section class="rail-card"><h3>Uma decisão por encontro</h3><ol><li>Definir o projeto.</li><li>Escolher um plano viável.</li><li>Responder à mudança.</li><li>Defender e acompanhar benefícios.</li></ol></section><section class="rail-card"><h3>Como usar os dados</h3><p>Inclua o caso completo como contexto na ferramenta de IA. Informe quais decisões seu grupo já tomou e quais premissas alterou.</p><a class="source" href="#aula/1/pratica">Começar a prática 1 →</a></section></div></div>`}
function guide(){return `<section class="lesson-head"><span class="pill">ORIENTAÇÕES AO ALUNO</span><h1>Aprender, aplicar e justificar.</h1><p class="lead">O objetivo é tomar decisões de projeto com evidências e usar a IA de forma crítica.</p></section><article class="reading"><h2>Como funciona a disciplina</h2><p>São quatro encontros online de três horas. O mesmo projeto evolui da abertura à defesa executiva. Em cada aula, estude os conceitos, realize a prática com seu grupo e registre as decisões e correções feitas às sugestões da IA.</p><p>ChatGPT e Claude são usados nas contas disponíveis ao grupo. Os prompts deste app não executam IA internamente. Não é necessário instalar conectores para completar os exercícios. Se não houver recurso de anexar arquivos, copie os trechos relevantes do caso para a conversa.</p><h2>O que você vai entregar</h2><div class="table-wrap"><table><thead><tr><th>Encontro</th><th>Entrega</th></tr></thead><tbody>${lessons.map(l=>`<tr><td>0${l.id}</td><td>${l.outcome}</td></tr>`).join('')}</tbody></table></div><h2>Avaliação proposta</h2><p>Os pesos abaixo orientam a disciplina. A nota de aprovação e o canal de entrega seguem as regras informadas pelo professor.</p><div class="table-wrap"><table><thead><tr><th>Critério</th><th>Pontos</th><th>Evidência esperada</th></tr></thead><tbody><tr><td>Enquadramento e evidências</td><td>20</td><td>Problema, valor, fronteiras e fontes.</td></tr><tr><td>Planejamento</td><td>25</td><td>Coerência entre escopo, prazo, custo e capacidade.</td></tr><tr><td>Desvios, riscos e mudança</td><td>25</td><td>Alternativas, impactos e decisão justificada.</td></tr><tr><td>Rotina com IA</td><td>15</td><td>Contrato de saída e dois testes documentados.</td></tr><tr><td>Reflexão individual</td><td>15</td><td>Sugestões aceitas, corrigidas ou rejeitadas e seus motivos.</td></tr></tbody></table></div><p>Os quatro primeiros critérios avaliam o grupo. A reflexão é individual. Qualidade visual e quantidade de prompts não substituem consistência. As perguntas de verificação do app são exercícios de autoavaliação, sem atribuição automática de nota.</p><h2>Acordos de trabalho</h2><ul><li>Use os dados sintéticos do caso. Não inclua informações pessoais ou sigilosas de sua organização.</li><li>Identifique fatos, hipóteses e recomendações.</li><li>Confira cálculos e afirmações relevantes na fonte.</li><li>Registre uma correção feita à IA em cada encontro.</li><li>Explique quem decide e quais ações exigem revisão humana.</li></ul><h2>Respostas e materiais</h2><details open><summary>Onde minhas respostas ficam?</summary><p>Elas permanecem apenas na memória desta aba durante a navegação. Fechar ou recarregar a página apaga os campos. Use “Baixar minhas respostas” ao terminar cada prática; o arquivo pode ser aberto em um editor de texto. O app não mantém contas de alunos nem envia respostas ao professor.</p></details><details><summary>Preciso acessar o Notion?</summary><p>Não para realizar as atividades. Conceitos, prompts, caso e modelos estão no app. Os links internos do material de origem foram omitidos nesta edição pública.</p></details><details><summary>O conteúdo acompanha alterações no Notion?</summary><p>Esta é uma edição preparada a partir do plano da disciplina. Alterações no Notion precisam ser incorporadas em uma nova atualização do app; não existe sincronização automática.</p></details><details><summary>Como apresentar no último encontro?</summary><p>Prepare cinco minutos sobre problema, evidências, plano, mudança e decisão. Inclua a rotina testada, seus limites e como os benefícios serão medidos. O professor organizará as apresentações conforme o número de grupos.</p></details><h2>Base da disciplina</h2><p>Adaptação dos treinamentos Claude para Gestores e ChatGPT Work para Gestão Ágil, organizada em quatro encontros de Gestão de Projetos com IA.</p><p class="disclaimer">Edição didática: setembro de 2026. A prática se concentra em conceitos e critérios de decisão; interfaces e recursos das ferramentas podem variar.</p></article>`}
function render(){const r=route();nav(r);$('#breadcrumb').textContent='Disciplina / '+(r.lesson?'Encontro 0'+r.lesson.id:r.page==='inicio'?'Visão geral':r.page==='caso'?'Caso integrador':r.page==='guia'?'Guia da disciplina':'Página não encontrada');$('#main').innerHTML=r.page==='inicio'?home():r.page==='aula'?lessonView(r.lesson,r.tab):r.page==='caso'?caseView():r.page==='guia'?guide():'<div class="empty"><h1>Página não encontrada</h1><a class="btn" href="#inicio">Voltar à disciplina</a></div>';document.title=(r.lesson?r.lesson.short:r.page==='caso'?'Caso Fluxo Claro':r.page==='guia'?'Guia da disciplina':'Sala de aprendizagem')+' | Gestão de Projetos com IA';}
function exportPractice(l,blank=false){let body='# Encontro '+l.id+' — '+l.title+'\n\n';body+='Grupo / aluno: ____________________\nData: ____________________\n\n';body+=l.fields.map((f,i)=>'## '+f[0]+'\n'+(blank?f[1]:(state.drafts[l.id]?.[i]||'[Não preenchido]'))).join('\n\n');body+='\n\n## Revisão\n'+l.checks.map((c,i)=>'- ['+(!blank&&state.checks[l.id]?.[i]?'x':' ')+'] '+c).join('\n');download((blank?'modelo':'respostas')+'-encontro-'+l.id+'.md',body,'text/markdown;charset=utf-8');toast(blank?'Modelo baixado.':'Respostas baixadas. Guarde o arquivo antes de sair.');}
document.addEventListener('input',e=>{const el=e.target;if(el.matches('textarea[data-field]')){const id=el.dataset.lesson;state.drafts[id]??={};state.drafts[id][el.dataset.field]=el.value;dirty=true;}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('input[data-check]')){state.checks[el.dataset.lesson]??={};state.checks[el.dataset.lesson][el.dataset.check]=el.checked;}if(el.name?.startsWith('quiz-'))state.quiz[el.name.split('-')[1]]=Number(el.value);});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,l=lessons.find(l=>l.id===Number(b.dataset.id));if(a==='case')download('caso-fluxo-claro.txt',caseText);if(a==='csv')download('atividades-fluxo-claro.csv','\uFEFF'+caseCSV,'text/csv;charset=utf-8');if(a==='prompt-file')download('prompt-encontro-'+l.id+'.txt',l.prompt);if(a==='export')exportPractice(l);if(a==='template')exportPractice(l,true);if(a==='copy'){try{await navigator.clipboard.writeText(l.prompt);toast('Prompt copiado. Inclua também as fontes do caso.');}catch{const range=document.createRange();range.selectNodeContents($('#prompt'));const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);toast('Selecione e copie o texto destacado pelo menu do dispositivo.');}}if(a==='quiz'){const value=state.quiz[l.id];const f=$('#quiz-feedback');if(value===undefined){f.className='feedback';f.textContent='Selecione uma alternativa antes de conferir.';return;}const good=value===l.quiz.answer;f.className='feedback'+(good?' good':'');f.textContent=(good?'Isso mesmo. ':'Reveja a interpretação. ')+l.quiz.explanation;}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
render();
